#!/usr/bin/env python3
import sys
import csv
import json
from decimal import Decimal, ROUND_HALF_UP

def normalize_category(cat: str) -> str:
    """Collapse whitespace and casefold. Blank becomes 'uncategorized'."""
    normalized = ' '.join(cat.split()).casefold()
    return normalized if normalized else 'uncategorized'

def main():
    if len(sys.argv) < 2:
        return
    input_filename = sys.argv[1]

    categories_sum = {}  # category -> total Decimal

    with open(input_filename, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            status = row['status'].strip().casefold()
            if status != 'paid':
                continue

            category = normalize_category(row['category'])
            amount = Decimal(row['amount']).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

            if category not in categories_sum:
                categories_sum[category] = Decimal('0')
            categories_sum[category] += amount

    # Sort categories by normalized name
    sorted_categories = sorted(categories_sum.items(), key=lambda x: x[0])

    # Build output structure
    categories_list = [
        {"category": cat, "total": str(total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))}
        for cat, total in sorted_categories
    ]

    grand_total = sum(categories_sum.values(), Decimal('0')).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

    output = {
        "categories": categories_list,
        "total": str(grand_total)
    }

    print(json.dumps(output))

if __name__ == '__main__':
    main()
